<section x-show="game?.results?.league" class="league-panel" aria-label="{{ __('League results') }}">
    <div class="league-heading"><h2>{{ __('League table') }}</h2><span>{{ __('Win 3 · Draw 1') }}</span></div>
    <table><thead><tr><th scope="col">{{ __('Team') }}</th><th scope="col">{{ __('P') }}</th><th scope="col">{{ __('GD') }}</th><th scope="col">{{ __('GF') }}</th><th scope="col">{{ __('Pts') }}</th></tr></thead><tbody><template x-for="(row, rank) in game?.results?.league?.table || []" :key="row.playerIndex"><tr :class="{'league-leader': game?.results?.winners.includes(row.playerIndex)}"><th scope="row"><span x-text="rank + 1"></span><b x-text="game.players[row.playerIndex].name"></b></th><td x-text="row.played"></td><td x-text="row.gd > 0 ? '+' + row.gd : row.gd"></td><td x-text="row.gf"></td><td><strong x-text="row.points"></strong></td></tr></template></tbody></table>
    <div class="league-fixtures"><template x-for="(fixture, index) in game?.results?.league?.matches || []" :key="index"><button class="fixture" @click="replayMatch(index)" :disabled="busy || simulating || (online && !room?.isHost)" :aria-label="t('Replay :home versus :away', { home: game.players[fixture.playerIndices[0]].name, away: game.players[fixture.playerIndices[1]].name })"><span x-text="game.players[fixture.playerIndices[0]].name"></span><strong x-text="fixture.goals.join(' – ')"></strong><span x-text="game.players[fixture.playerIndices[1]].name"></span><small>↻ {{ __('Replay') }}</small></button></template></div>
</section>
